contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount >= 0);
        // attempt a first airDrop from this contract
        bool reverted1;
        try c.airDrop() { reverted1 = false; } catch { reverted1 = true; }
        uint balAfter1 = c.tokenBalance(address(this));
        if (!reverted1) {
            assert(balAfter1 == 20);
        } else {
            assert(balAfter1 == 0);
        }
        // a second airDrop should revert because hasNoBalance
        bool reverted2;
        try c.airDrop() { reverted2 = false; } catch { reverted2 = true; }
        uint balAfter2 = c.tokenBalance(address(this));
        assert(reverted2 && balAfter2 == balAfter1);
        // if first succeeded, second must revert, and balance unchanged
        if (!reverted1) {
            assert(balAfter2 == 20);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        // First airDrop: should succeed and set caller's balance to 20
        bool reverted1;
        try c.airDrop() { reverted1 = false; } catch { reverted1 = true; }
        uint bal1 = c.tokenBalance(address(this));

        // Second airDrop: must revert because hasNoBalance fails
        bool reverted2;
        try c.airDrop() { reverted2 = false; } catch { reverted2 = true; }
        uint bal2 = c.tokenBalance(address(this));

        // General rule: if first call succeeds, balance is exactly 20 and second call reverts leaving balance at 20
        assert(!reverted1 || (bal1 == 20 && reverted2 && bal2 == 20));
    }

    receive() external payable {}
}

